/* Coordinate-system adaptation (documented, math-preserving): the      */
/* engine world is y-DOWN (PSX); the GLB is glTF y-UP. The whole light  */
/* computation runs in glTF world space with the light direction and    */
/* offset mapped once from Harry's bone frame to the live camera frame: */
