/* torso in the engine (Game_FlashlightAttributesFix):                  */
/*   engine-local (x,y,z) -> camera-local (x,-y,-z)                     */
/*     (+Z engine forward  -> -Z camera forward (three.js),             */
/*      +Y engine down    -> -Y camera up)                             */
/* A global axis reflection preserves every dot product, so the engine  */
/* math is bit-equivalent in the reflected frame.                      */
/* Engine mesh normals point INTO the surface (verified: both the       */
/* enum-1 mesh light and the enum-2 N.L light are only correct with     */
